WITH lines AS (SELECT id, plan, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_limits) t AS element) SELECT *, CUME_DIST() OVER (PARTITION BY currency ORDER BY element DESC NULLS FIRST) element_cume_dist, DENSE_RANK() OVER (ORDER BY element DESC NULLS LAST) element_dense_rank, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY element DESC NULLS LAST) element_percent_rank FROM lines
